class Solution:
    def countFullSets(self, s: str) -> int:
        n, total = len(s), 0
        for i in range(n):
            seen = set()
            for j in range(i, n):
                seen.add(s[j])
                if len(seen) == 3:
                    total += n - j
                    break
        return total

