class Solution {
    public long countFullSets(String s) {
        int n = s.length();
        long total = 0;
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (int j = i; j < n; j++) {
                mask |= 1 << (s.charAt(j) - 'a');
                if (mask == 7) { total += n - j; break; }
            }
        }
        return total;
    }
}

