class Solution {
    public long countFullSets(String s) {
        int[] last = {-1, -1, -1};
        long total = 0;
        for (int i = 0; i < s.length(); i++) {
            last[s.charAt(i) - 'a'] = i;
            total += Math.min(last[0], Math.min(last[1], last[2])) + 1;
        }
        return total;
    }
}

